// === Tab: mySketch.js ===
// This sketch uses p5play v3. Learn how to use it at p5play.org!

function setup() {
	new Canvas('1:1');
	world.gravity.y = canvas.w * 0.012;
	strokeWeight(canvas.w * 0.003);
	noStroke();

	let w99 = canvas.w * 0.99;

	lines = new Group();
	lines.collider = 'static';
	lines.color = () => color(random(100, 150), random(100, 250), random(230, 255));

	for (let i = 0; i < 11; i++) {
		let x = i * canvas.w * 0.1;
		new lines.Sprite([
			[0, canvas.h - x],
			[canvas.w - x, canvas.h]
		]);

		new lines.Sprite([
			[canvas.w - x, 0],
			[canvas.w, canvas.h - x]
		]);
	}

	let minVel = canvas.w * 0.02;
	let maxVel = canvas.w * 0.03;

	water = new Group();
	water.diameter = canvas.w * 0.02;
	water.x = w99;
	water.y = w99;
	water.vel.y = () => -map(world.physicsTime > 4 ? mouse.y : 0, 0, canvas.w, minVel, maxVel);
	water.color = () => color(random(100, 150), random(100, 250), random(230, 255));
	water.life = 240;
}

function draw() {
	background('#001d39');
	if (frameCount % 6 == 0) new water.Sprite();

	for (let drop of water) {
		drop.d = canvas.w * drop.life / 7000;
	}
}
